app.get("/sitemap.xml", (c) => {
  const urls = ["https://code402.dev/", "https://code402.dev/llms.txt"];
  c.header("content-type", "application/xml");
  return c.body(
    `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
` + urls.map((u) => `  <url><loc>${u}</loc></url>`).join("\n") + `
</urlset>
`
  );
});
var LEGACY = "https://code402-edge-prod.akrivis.workers.dev";
var LEGACY_PATHS = ["/trust", "/docs", "/pricing", "/x402.json"];
for (const p of LEGACY_PATHS) {
  const proxy = /* @__PURE__ */ __name((c) => {
    const url = new URL(c.req.url);
    return fetch(LEGACY + url.pathname + url.search, c.req.raw);
  }, "proxy");
  app.all(p, proxy);
  app.all(`${p}/*`, proxy);
}
app.get("/sell", (c) => c.redirect("https://gateway.code402.dev/v1/sellers", 302));
